/* ---------- Gallery ---------- */

function Gallery({ full, L }) {
  const [active, setActive] = useState(0);
  const catsKey = ["All", "Weddings", "Decor", "Events", "Cars"];
  const hasRealMedia = media.gallery.length > 0;
  const placeholderTiles = [
    { cat: "Weddings", h: "h-72" }, { cat: "Decor", h: "h-48" }, { cat: "Events", h: "h-60" },
    { cat: "Cars", h: "h-52" }, { cat: "Weddings", h: "h-64" }, { cat: "Decor", h: "h-56" },
    { cat: "Events", h: "h-48" }, { cat: "Weddings", h: "h-60" },
  ];
  const heights = ["h-72", "h-48", "h-60", "h-52", "h-64", "h-56", "h-48", "h-60"];
  const tiles = hasRealMedia
    ? media.gallery.map((m, i) => ({ cat: m.cat, h: heights[i % heights.length], src: m.src }))
    : placeholderTiles;
  const shown = full ? tiles : tiles.slice(0, 6);
  const activeCat = catsKey[active];
  const filtered = activeCat === "All" ? shown : shown.filter((t) => t.cat === activeCat);
  const tones = ["#1C1712", "#B98F3B", "#C98B7A", "#6B5F4F", "#3A2E22"];
  return (
    <section className="py-24 px-6" style={{ backgroundColor: business.colors.ivory }}>
      <div className="max-w-6xl mx-auto">
        <Reveal className="flex flex-wrap items-end justify-between gap-6 mb-10">
          <div>
            <Eyebrow>{L.gallery.eyebrow}</Eyebrow>
            <h2 className="font-serif text-4xl md:text-5xl" style={{ color: business.colors.ink }}>{L.gallery.title}</h2>
          </div>
          {full && (
            <div className="flex flex-wrap gap-2">
              {L.gallery.cats.map((c, i) => (
                <button key={i} onClick={() => setActive(i)} className="px-4 py-2 rounded-full text-xs tracking-wide"
                  style={{ backgroundColor: active === i ? business.colors.ink : "#fff", color: active === i ? business.colors.ivory : "#6B5F4F", border: "1px solid #EDE4D3" }}>
                  {c}
                </button>
              ))}
            </div>
          )}
        </Reveal>
        <div className="columns-2 md:columns-3 gap-4 space-y-4">
          {filtered.map((t, i) => (
            <Reveal key={i} delay={(i % 4) * 80} className={`break-inside-avoid rounded-xl overflow-hidden ${t.h} relative`}>
              {t.src ? (
                <>
                  <img src={t.src} alt={t.cat} className="w-full h-full object-cover" />
                  <div className="absolute inset-x-0 bottom-0 p-4" style={{ background: "linear-gradient(180deg, transparent, rgba(0,0,0,0.55))" }}>
                    <span className="text-xs uppercase tracking-widest text-white/90">{L.gallery.cats[catsKey.indexOf(t.cat)]}</span>
                  </div>
                </>
              ) : (
                <div className="w-full h-full flex items-end p-4" style={{ backgroundColor: tones[i % tones.length] }}>
                  <span className="text-xs uppercase tracking-widest text-white/80">
                    {L.gallery.cats[catsKey.indexOf(t.cat)]}
                  </span>
                </div>
              )}
            </Reveal>
          ))}
        </div>
      </div>
    </section>
  );
}

